'use client';

import { useState, useEffect } from 'react';

export interface RoundIntro {
  eyebrow: string;
  title: string;
  lines: string[];
}

export interface RoundOutro {
  eyebrow: string;
  title?: string;
  fact: string;
  tagline?: string;
}

export const ROUND_INTROS: Record<1 | 2 | 3, RoundIntro> = {
  1: {
    eyebrow: 'ROUND 1 OF 3',
    title: 'Spot the Fake',
    lines: [
      'You get images, one at a time.',
      '{n} seconds each — decide if it is a real photo or generated by AI.',
      "You won't be told if you were right during the game. All scores come at the end.",
    ],
  },
  2: {
    eyebrow: 'ROUND 2 OF 3',
    title: 'Draw vs AI',
    lines: [
      "You'll be given one target object to draw.",
      '{n} seconds on the grid using your finger or mouse.',
      'Our on-device AI will analyze your drawing live when you submit.',
    ],
  },
  3: {
    eyebrow: 'ROUND 3 OF 3',
    title: 'You vs AIDA',
    lines: [
      'One challenge question for today.',
      '{n} seconds to drag the slider to your best guess.',
      'The closer your guess to the exact value, the higher you score.',
    ],
  },
};

export const ROUND_OUTROS: Record<1 | 2 | 3, RoundOutro> = {
  1: {
    eyebrow: 'ROUND 1 COMPLETE',
    title: 'FUN FACT',
    fact:
      'AI mistakes are no longer limited to extra fingers... the hardest clues can be inconsistent reflections, lighting or text.',
    tagline: 'SAME MINDS. DIFFERENT POSSIBILITIES. A BRIGHTER TOMORROW.',
  },
  2: {
    eyebrow: 'ROUND 2 COMPLETE',
    title: 'FUN FACT',
    fact:
      'Our model was trained with approximately 300,000 human doodles across 15 drawing categories. You will learn how to do so in your PDAII and ML courses.',
    tagline: 'SAME MINDS. DIFFERENT POSSIBILITIES. A BRIGHTER TOMORROW.',
  },
  3: {
    eyebrow: 'ALL ROUNDS COMPLETE',
    title: 'FINAL SCORING',
    fact: 'Scoring your challenge performance and tallying the leaderboard…',
    tagline: 'CREATIVITY STILL WINS.',
  },
};

export function Interstitial({
  intro,
  outro,
  seconds = 7,
  timerValue,
  onDone,
}: {
  intro?: RoundIntro;
  outro?: RoundOutro;
  seconds?: number;
  timerValue?: number;
  onDone: () => void;
}) {
  const [remaining, setRemaining] = useState(seconds);

  useEffect(() => {
    if (remaining <= 0) {
      onDone();
      return;
    }
    const t = setTimeout(() => setRemaining((r) => r - 1), 1000);
    return () => clearTimeout(t);
  }, [remaining, onDone]);

  const content = intro ?? outro;
  if (!content) return null;
  const isIntro = Boolean(intro);

  return (
    <main className="relative flex min-h-dvh flex-col overflow-hidden bg-[var(--color-px-bg)] text-[var(--color-ink)]">
      {/* Background with circuit glow */}
      <div
        className="absolute inset-0 z-0 bg-cover bg-center opacity-35 pointer-events-none"
        style={{ backgroundImage: "url('/backgrounds/circuit-9x16.png')" }}
        aria-hidden="true"
      />
      <div className="arena-bg z-0 opacity-70" aria-hidden="true" />

      <div className="relative z-10 mx-auto flex w-full max-w-md flex-1 flex-col justify-between px-5 py-6 sm:py-8">
        {/* Top Header */}
        <div className="text-center">
          <span className="px-chip text-[9px] sm:text-[10px]">
            {content.eyebrow}
          </span>
        </div>

        {/* Center Content */}
        <div className="my-auto flex flex-col items-center text-center">
          {isIntro && intro && (
            <div className="w-full">
              <h1 className="px-title-yellow text-2xl sm:text-3xl leading-tight">
                {intro.title.toUpperCase()}
              </h1>
              <ul className="px-panel mt-6 space-y-3 px-5 py-5 text-left bg-[#0d1440]/90">
                {intro.lines.map((line, i) => (
                  <li
                    key={i}
                    className="flex items-start gap-3 text-xs leading-relaxed text-slate-200"
                  >
                    <span className="mt-1.5 h-2 w-2 shrink-0 bg-[var(--color-px-cyan)] shadow-[0_0_6px_var(--color-px-cyan)]" />
                    <span>
                      {timerValue != null
                        ? line.replace('{n}', String(timerValue))
                        : line.replace('{n}', '')}
                    </span>
                  </li>
                ))}
              </ul>
            </div>
          )}

          {!isIntro && outro && (
            <div className="w-full flex flex-col items-center">
              {/* Fun fact illustration: Mascot with Dual-Brain */}
              <div className="relative mb-4 flex items-center justify-center">
                <img
                  src="/sprites/mascot-girl-cheer.png"
                  alt="AIDA Mascot"
                  className="pixelated h-32 w-auto drop-shadow-[0_4px_12px_rgba(0,0,0,0.8)]"
                />
              </div>

              <h2 className="px-title-yellow text-2xl tracking-wider">
                {outro.title ?? 'FUN FACT'}
              </h2>

              <div className="px-panel mt-4 p-5 text-center bg-[#0d1440]/95 border-[3px] border-[#070c26]">
                <p className="text-xs sm:text-sm leading-relaxed text-slate-200 font-medium">
                  {outro.fact}
                </p>
                {outro.tagline && (
                  <p className="mt-4 pt-3 border-t border-[#2c4ba8]/50 font-px text-[8px] text-[#35e0ff] tracking-wider">
                    {outro.tagline}
                  </p>
                )}
              </div>
            </div>
          )}
        </div>

        {/* Bottom CTA */}
        <div className="w-full pt-4">
          <button
            onClick={onDone}
            className="px-btn px-btn-yellow min-h-[58px] w-full py-4 text-xs tracking-wider"
          >
            {isIntro ? "I'M READY" : 'NEXT ROUND →'}
            <span className="tabular ml-2 opacity-70">({remaining}s)</span>
          </button>
          <p className="mt-2 text-center text-[10px] text-slate-400">
            This screen is not timed against your 60-second game score.
          </p>
        </div>
      </div>
    </main>
  );
}
